{
  "metadati": {
    "data_sintetica": "2026-04-16",
    "chiave_indagine": null,
    "descrizione": "Un delegato della Rilevazione sulle tecnologie dell’informazione e della comunicazione nelle imprese, codice PSN IST-01175, segnala che il recupero dell’accesso con {{cod_utente_1}} non riesce perché non può accedere alla vecchia casella {{email_1}}. Comunica il nominativo {{persona_1}} e viene indirizzato a richiedere assistenza per l’aggiornamento del recapito, senza promessa di modifica diretta dell’account."
  },
  "conversazione": [
    {
      "sender": "Utente",
      "testo": "Per la Rilevazione sulle tecnologie dell’informazione e della comunicazione nelle imprese, codice PSN IST-01175, devo recuperare l’accesso. Sono il delegato dell’impresa, non il responsabile."
    },
    {
      "sender": "Agente",
      "testo": "Per chiarire la situazione: hai già effettuato un tentativo di recupero? Confermi quindi di operare con il ruolo di delegato e non di responsabile?"
    },
    {
      "sender": "Utente",
      "testo": "Sì, confermo di essere delegato. Ho già provato il recupero usando il codice utente {{cod_utente_1}}, ma le comunicazioni arrivano alla vecchia casella {{email_1}}, a cui non ho più accesso."
    },
    {
      "sender": "Agente",
      "testo": "Se non hai accesso alla vecchia casella, il tentativo di recupero non può risolvere il problema. Puoi richiedere assistenza per l’aggiornamento del recapito, senza che questo comporti una modifica diretta dell’account. Per associare correttamente la segnalazione, puoi indicare il nominativo collegato all’utenza?"
    },
    {
      "sender": "Utente",
      "testo": "Il nominativo associato è {{persona_1}}. Mi serve aggiornare il recapito perché la vecchia casella non è più utilizzabile."
    },
    {
      "sender": "Agente",
      "testo": "Nella richiesta di assistenza indica che sei delegato per l’indagine, il codice utente {{cod_utente_1}}, il nominativo {{persona_1}} e il mancato accesso alla vecchia casella {{email_1}}. L’assistenza potrà verificare l’aggiornamento del recapito necessario al recupero."
    },
    {
      "sender": "Utente",
      "testo": "Va bene, inoltrerò la richiesta specificando che il recupero non si completa per il mancato accesso alla vecchia casella."
    },
    {
      "sender": "Agente",
      "testo": "È l’indicazione corretta: specifica anche il ruolo di delegato e il riferimento alla Rilevazione sulle tecnologie dell’informazione e della comunicazione nelle imprese, codice PSN IST-01175."
    },
    {
      "sender": "Utente",
      "testo": "Procedo in questo modo."
    },
    {
      "sender": "Agente",
      "testo": "La richiesta potrà così essere valutata per l’aggiornamento del recapito e il successivo recupero dell’accesso."
    }
  ],
  "trattamento_atteso": {
    "mascherare": [
      {
        "segnaposto": "{{cod_utente_1}}",
        "tipo": "COD_UTENTE",
        "sostituzione": "[COD_UTENTE_1]"
      },
      {
        "segnaposto": "{{email_1}}",
        "tipo": "EMAIL",
        "sostituzione": "[EMAIL_1]"
      },
      {
        "segnaposto": "{{persona_1}}",
        "tipo": "PERSON",
        "sostituzione": "[PERSON_1]"
      }
    ],
    "conservare": [
      "Il ruolo di responsabile o delegato, necessario per chiarire la posizione dell’utente.",
      "Il nome e il codice PSN dell’indagine: Rilevazione sulle tecnologie dell’informazione e della comunicazione nelle imprese, IST-01175.",
      "Il mancato accesso alla vecchia casella come motivazione del recupero non riuscito e della richiesta di aggiornamento del recapito."
    ],
    "motivazione": "Codice utente, indirizzo email e nominativo sono dati personali da mascherare. Il ruolo, i riferimenti pubblici dell’indagine e il problema di accesso alla vecchia casella sono invece informazioni di contesto utili alla gestione della richiesta."
  }
}
